import {resolveTurn,die,nextPlayer,csvCell} from './engine.js';
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data;try{const r=await fetch('./data.json');if(!r.ok)throw Error();data=await r.json();}catch{$('setup').innerHTML='<h2>Data se nepodařilo načíst</h2><p>Obnovte stránku. Při místním spuštění použijte HTTP server podle README.</p>';throw Error('Data nejsou dostupná');}
const palette=['#eeac82','#f3ce76','#88d6bf','#92c6e8','#d2a1db','#f1a5bb'], rowColors=['#9b4947','#bb7048','#a58d40','#3e8179','#417e9e','#585999','#855da1','#9a8459'];
const key='lila-cesta-v1';let state=null,backup=null,selected=1,busy=false,storageOK=true;
function xy(n){const r=Math.floor((n-1)/9),c=(n-1)%9;return {x:(r%2?8-c:c)*100+50,y:(7-r)*90+40};}
for(let visual=0;visual<72;visual++){
 const row=7-Math.floor(visual/9),col=visual%9,n=row*9+(row%2?9-col:col+1),f=data.fields[n-1],to=data.arrows[n]||data.snakes[n];
 const b=document.createElement('button');b.className='cell'+(n===68?' goal-cell':'');b.id='cell-'+n;b.style.setProperty('--row',rowColors[row]);b.setAttribute('aria-label',`${n}. ${f.name}${to?`, ${data.arrows[n]?'šíp':'had'} na ${to}`:''}`);b.innerHTML=`<span class="cell-number">${String(n).padStart(2,'0')}</span>${to?`<span class="cell-link">${data.arrows[n]?'↗':'∿'} ${to}</span>`:''}<span class="cell-name">${esc(f.name)}</span>`;b.onclick=()=>showField(n);$('cells').append(b);
}
let paths='<defs><marker id="arrowhead" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="#91e2ca" stroke-width="1.2"/></marker></defs>';
for(const [a,b] of Object.entries(data.arrows)){const p=xy(+a),q=xy(b);paths+=`<path d="M${p.x+15},${p.y}L${q.x+15},${q.y}" stroke="#0a162a" stroke-width="6" opacity=".5"/><path d="M${p.x+15},${p.y}L${q.x+15},${q.y}" stroke="#91e2ca" stroke-width="2.1" opacity=".85" marker-end="url(#arrowhead)"/><circle cx="${p.x+15}" cy="${p.y}" r="3" fill="#91e2ca"/>`;}
for(const [a,b] of Object.entries(data.snakes)){const p=xy(+a),q=xy(b),dx=q.x-p.x,dy=q.y-p.y;const d=`M${p.x-12},${p.y} C${p.x+45},${p.y+dy*.33} ${q.x-65},${q.y-dy*.33} ${q.x-12},${q.y}`;paths+=`<path d="${d}" fill="none" stroke="#3c1b32" stroke-width="8" opacity=".7"/><path d="${d}" fill="none" stroke="#e69aab" stroke-width="4" opacity=".9"/><path d="${d}" fill="none" stroke="#fbd0b7" stroke-width="1.3" stroke-dasharray="2 7"/><ellipse cx="${p.x-12}" cy="${p.y}" rx="7" ry="5" fill="#eeafaf"/><circle cx="${p.x-14}" cy="${p.y-1}" r="1.3" fill="#262039"/>`;}
$('paths').innerHTML=paths;
function save(){try{if(state)localStorage.setItem(key,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}$('save-state').textContent=state?(storageOK?'Uloženo v tomto prohlížeči':'Ukládání není dostupné · použijte export'):'Zatím bez rozehrané hry';}
function showField(n){selected=n;const f=data.fields[n-1];document.querySelector('.cell.selected')?.classList.remove('selected');$('cell-'+n).classList.add('selected');$('field-number').textContent=String(n).padStart(2,'0');$('field-term').textContent=f.term;$('field-name').textContent=f.name;$('field-meaning').textContent=f.meaning;$('field-question').textContent=f.question;const to=data.arrows[n]||data.snakes[n];$('field-link').textContent=to?`${data.arrows[n]?'Šíp stoupá':'Had klesá'} na ${to} · ${data.fields[to-1].name}.`:(n===68?'Cíl cesty. Vrať se ke svému záměru.':'');$('note').disabled=!state;$('note').value=state?.players[state.active]?.notes?.[n]||'';$('note-state').textContent=state?`Zápis hráče ${state.players[state.active].name} k poli ${n}.`:'Zápisky se zpřístupní po zahájení hry.';}
function render(){
 $('setup').hidden=!!state;$('play').hidden=!state;if(!state){$('tokens').innerHTML='';showField(selected);return;}
 const p=state.players[state.active],done=state.players.every(x=>x.finished);
 $('active-name').textContent=done?'Cesty jsou uzavřené':p.name;$('turn-label').textContent=done?'SPOLEČNÉ OHLÉDNUTÍ':'NA ŘADĚ';$('active-intention').textContent=p.intention||state.intention||'Nech si prostor pro vlastní otázku.';
 $('players').innerHTML=state.players.map((p,i)=>`<span class="player-chip ${i===state.active?'active':''}"><i style="--color:${palette[i]}"></i>${esc(p.name)} · ${p.finished?'✓ 68':p.position??'čeká'}</span>`).join('');
 $('series').textContent=state.rolls.length?'Série: '+state.rolls.join(' + '):'';$('roll').disabled=busy||state.awaitNext||done;$('next').hidden=!state.awaitNext||done;$('undo').disabled=!backup||busy;$('new').disabled=busy;
 $('status').textContent=state.message||'';$('roll-info').textContent=done?'Každý si odnese vlastní poznání.':state.rolls.length?'Šestka: hoď ještě jednou.':p.position===null?'První šestka otevře cestu.':`Pole ${p.position} · ${data.fields[p.position-1].name}`;
 $('tokens').innerHTML=state.players.map((p,i)=>{const v=xy(p.position??68);return `<div class="token" style="--color:${palette[i]};left:calc(${(v.x-30+(i%3)*22)/9}% - 10px);top:calc(${(v.y-3+Math.floor(i/3)*23)/7.2}% - 10px)">${i+1}</div>`;}).join('');
 $('journal').innerHTML=state.history.length?state.history.slice().reverse().map(h=>`<article class="log-entry"><div><strong>${esc(state.players[h.player].name)}</strong><br><small>${new Date(h.time).toLocaleTimeString('cs-CZ',{hour:'2-digit',minute:'2-digit'})}</small></div><div><strong>${esc(h.rolls.join(' + '))} · ${esc(h.summary)}</strong>${h.path.map(n=>`<p>${n} · ${esc(data.fields[n-1].name)}${state.players[h.player].notes[n]?'<br><em>'+esc(state.players[h.player].notes[n])+'</em>':''}</p>`).join('')}</div></article>`).join(''):'<p class="muted">První hod otevře váš deník.</p>';
 showField(selected);save();
}
let setupPlayers=[{name:'',intention:''},{name:'',intention:''}];
function renderSetup(){ $('player-inputs').innerHTML=setupPlayers.map((p,i)=>`<div class="player-form"><div class="input-row"><div><label for="name-${i}">Hráč ${i+1}</label><input id="name-${i}" data-player="${i}" data-prop="name" maxlength="40" placeholder="Jméno" value="${esc(p.name)}" required></div>${setupPlayers.length>1?`<button type="button" data-remove="${i}" aria-label="Odebrat hráče ${i+1}">✕</button>`:''}</div><input class="personal-intent" aria-label="Osobní záměr hráče ${i+1}" maxlength="300" data-player="${i}" data-prop="intention" placeholder="Osobní záměr (nepovinný)" value="${esc(p.intention)}"></div>`).join('');$('add-player').hidden=setupPlayers.length>=6; }
$('player-inputs').oninput=e=>{if(e.target.dataset.player!==undefined)setupPlayers[+e.target.dataset.player][e.target.dataset.prop]=e.target.value;};
$('player-inputs').onclick=e=>{const b=e.target.closest('[data-remove]');if(b){setupPlayers.splice(+b.dataset.remove,1);renderSetup();}};
$('add-player').onclick=()=>{if(setupPlayers.length<6){setupPlayers.push({name:'',intention:''});renderSetup();}};
$('setup-form').onsubmit=e=>{e.preventDefault();if(setupPlayers.some(p=>!p.name.trim()))return;state={version:1,rules:'johari-series-v1',created:new Date().toISOString(),intention:$('intention').value,players:setupPlayers.map(p=>({name:p.name.trim(),intention:p.intention.trim(),position:null,finished:false,notes:{}})),active:0,rolls:[],history:[],awaitNext:false,message:'Figurky před zrozením čekají na 68. Hoď šestku.'};backup=null;selected=1;render();};
$('roll').onclick=async()=>{if(busy||!state||state.awaitNext||state.players.every(p=>p.finished))return;backup=structuredClone(state);busy=true;render();$('die').classList.add('rolling');const n=die();await new Promise(r=>setTimeout(r,450));$('die').classList.remove('rolling');$('die').textContent=['','⚀','⚁','⚂','⚃','⚄','⚅'][n];$('die').setAttribute('aria-label',`Padlo ${n}`);state.rolls.push(n);busy=false;
 if(n===6){state.message='Šestka dává další hod. Přesun se vyhodnotí po ukončení série.';render();return;}
 const p=state.players[state.active],r=resolveTurn(p,state.rolls,data);p.position=r.position;p.finished=r.finished;
 let summary=r.kind==='waiting'?'Čekání na první šestku':r.kind==='overshoot'?'Překročení 72 · figurka zůstává':r.path.map(x=>`${x} ${data.fields[x-1].name}`).join(' → ');
 if(state.rolls.length===4)summary='Tři šestky se ruší · '+summary;
 state.history.push({time:new Date().toISOString(),player:state.active,rolls:[...state.rolls],path:r.path,kind:r.kind,position:r.position,summary});state.message=p.finished?`${p.name} dorazil/a na 68. Zapiš si, co se vyjasnilo.`:summary;state.rolls=[];state.awaitNext=true;if(r.path.length)selected=r.path[0];render();};
$('next').onclick=()=>{if(!state?.awaitNext)return;backup=null;const n=nextPlayer(state.players,state.active);if(n<0)return;state.active=n;state.awaitNext=false;state.message='Nový tah. Zastav se na chvíli u svého záměru.';selected=state.players[n].position||1;render();};
$('undo').onclick=()=>{if(!backup)return;state=backup;backup=null;render();};
$('note').oninput=()=>{if(!state)return;state.players[state.active].notes[selected]=$('note').value;save();};
$('note').onchange=()=>render();
$('new').onclick=()=>{modal('Začít znovu?',`<p>Nová hra nahradí rozehranou cestu v tomto prohlížeči. Můžeš si ji nejprve exportovat.</p><div class="export-options"><button id="backup-first">Exportovat JSON</button><button id="reset-confirm" class="primary">Začít novou hru</button></div>`);$('backup-first').onclick=()=>exportJSON();$('reset-confirm').onclick=()=>{state=null;backup=null;try{localStorage.removeItem(key);}catch{}$('journal').innerHTML='<p class="muted">Tady začne nová cesta.</p>';$('modal').close();render();save();};};
function modal(title,body){$('modal-title').textContent=title;$('modal-body').innerHTML=body;$('modal').showModal();}$('close-modal').onclick=()=>$('modal').close();
$('modal').onclick=e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('modal').close();}};
const rulesHTML=`<p>Líla je prostor pro vlastní otázky. Nejde o závod; každý uzavírá svou cestu na poli <strong>68</strong>. Čísla na kostce slouží k pohybu, význam jim dáváš vlastní úvahou.</p><ol><li><strong>Příprava.</strong> Zadejte jména a případně osobní záměry. Hraje 1–6 lidí u jednoho zařízení. Čekající figurky jsou na 68, ale cesta ještě není dokončená.</li><li><strong>Vstup.</strong> Dokud nepadne šestka, čekáš. První šestka znamená vstup přes zrození na pole 6 a další hod.</li><li><strong>Série šestek.</strong> Hoď znovu po každé šestce. Pro přehlednost se celá série vyhodnotí až po hodu 1–5. Jedna či dvě šestky se přičtou; přesně tři šestky před závěrečným hodem se zruší. Při čtyřech a více se počítá všechno. Při zrození se po zrušení tří šestek počítá poslední hod z pole 1.</li><li><strong>Pohyb.</strong> Pokračuj vzestupně po číslech. Například z 20 série 6, 2 vede na 28 a šípem na 50. Vyhodnocujeme jen konečné pole série a následný přesun. Mezilehlá pole nepůsobí.</li><li><strong>Hadi a šípy.</strong> Přesuny jsou povinné. Zastav se u významu obou polí; kliknutím na plán si zobrazíš i cíl. Figurkám nevadí společné pole.</li><li><strong>Cíl a horní řada.</strong> Jen přesný dopad na 68 (nebo šíp 54–68) dokončí cestu. Přechod přes 68 nezastavuje. Na 69–71 pokračuj k 72, had tě vrátí na 51. Pokud součet přesáhne 72, zůstáváš na místě. Při dosud nevyhodnoceném vstupu zůstaneš v takovém případě na 6.</li><li><strong>Ohlédnutí.</strong> Před předáním tahu si napiš myšlenku. Dokončení hráči už nehází; ostatní mohou pokračovat. Hru lze kdykoli přerušit a exportovat.</li></ol><h3>Konkrétní příklady</h3><p>30 + (6, 6, 6, 4) = 34. Čtyři šestky a 1 znamenají posun o 25. Z 67 s hodem 2 jdeš na 69; s hodem 6 a 1 se nepohneš. Z 71 s hodem 1 následuje had 72–51.</p><h3>Naše sjednocení pravidel</h3><p>Používáme 72polovou mapu známou z Džóharího pojetí a součtové vyhodnocení šestek. Historické i současné edice se v detailech liší. Tiskový návod a tento web používají shodnou variantu; především se nevyskakuje automaticky z 72 se zbytkem hodu.</p><p>Každý smí otázku přeskočit a ponechat si odpověď pro sebe. Pole nejsou hodnocením člověka ani předpovědí budoucnosti.</p>`;
$('rules').onclick=()=>modal('Jak se vydat na cestu',rulesHTML);
$('print').onclick=()=>modal('Vezmi Lílu ke stolu',`<p>Originální vektorový plán obsahuje všech 72 českých názvů a všech 20 přesunů. Příručka nabízí pravidla, výklady, otázky a místo pro závěrečné ohlédnutí.</p><a class="primary" href="downloads/Lila_herni_plan_A3.pdf" download>Plán · A3 na šířku</a><a class="primary" href="downloads/Lila_navod_A4.pdf" download>Průvodce · A4</a><h3>Doporučený tisk</h3><p>Plán tiskni barevně na A3, ve skutečné velikosti (100 %), bez ořezu. Obsah má bezpečné okraje. Na A4 zvol přizpůsobení celé stránce; názvy budou menší. Pro větší desku použij v tiskovém programu režim plakátu na více listů. Příručku tiskni na A4, ideálně oboustranně.</p>`);
$('sources').onclick=()=>modal('Prameny a autorské pojetí',`<p>Líla patří do rodiny indických her poznání. Neexistuje jediný doložený původní plán pro všechny tradice. Zde používáme 72polovou mapu popularizovanou Harišem Džóharím.</p><ul><li><a href="https://www.sanatansociety.com/hinduism_books/hb_leela_karma.htm" target="_blank" rel="noopener">Sanatan Society: Leela, the Game of Knowledge</a></li><li><a href="https://www.simonandschuster.com/books/The-Yoga-of-Snakes-and-Arrows/Harish-Johari/9781594771781" target="_blank" rel="noopener">Harish Johari: The Yoga of Snakes and Arrows</a></li><li><a href="https://www.themathesontrust.org/papers/hinduism/Schmidt-Madsen-Road_Maps_for_the_Soul.pdf" target="_blank" rel="noopener">Jacob Schmidt-Madsen: Road Maps for the Soul (2013)</a></li><li><a href="https://www.leela.quest/board/vedic/en" target="_blank" rel="noopener">Leela Quest: názvy a propojení polí</a></li><li><a href="https://leelaatlas.com/how-to-play" target="_blank" rel="noopener">Leela Atlas: srovnání současných pravidel</a></li><li><a href="https://www.labrix.eu/vydane-knihy.html#leela" target="_blank" rel="noopener">Labrix: české vydání jako orientační reference</a></li></ul><p>Grafika, české komentáře a otázky vznikly pro tento projekt. Nejde o kopii ilustrací ani textů komerčních edic. Tradiční pojmy jsou místy přeloženy volně pro srozumitelnost. Prameny ověřeny 20. 11. 2026.</p>`);
$('library').onclick=()=>{modal('Prozkoumej všech 72 polí','<label for="field-search">Najít název nebo číslo</label><input id="field-search" class="search" placeholder="Např. soucit, 17…"><div id="field-list" class="field-list"></div>');function filter(){const q=$('field-search').value.toLocaleLowerCase('cs');$('field-list').innerHTML=data.fields.filter(f=>(f.id+' '+f.name+' '+f.term).toLocaleLowerCase('cs').includes(q)).map(f=>`<button data-field="${f.id}">${f.id} · ${esc(f.name)}</button>`).join('');}$('field-search').oninput=filter;$('field-list').onclick=e=>{const b=e.target.closest('[data-field]');if(b){$('modal').close();showField(+b.dataset.field);$('field-card').scrollIntoView({behavior:'smooth',block:'nearest'});}};filter();};
function download(name,text,type){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function exportJSON(){if(state)download('Lila_cesta.json',JSON.stringify(state,null,2),'application/json');}
function exportCSV(){if(!state)return;const rows=[['Hráč','Záměr','Čas','Hody','Trasa','Výsledek','Poznámky']];for(const h of state.history){const p=state.players[h.player];rows.push([p.name,p.intention||state.intention,h.time,h.rolls.join(' + '),h.path.join(' → '),h.summary,h.path.map(n=>p.notes[n]?`${n}: ${p.notes[n]}`:'').filter(Boolean).join(' | ')]);}for(const p of state.players)for(const [n,note]of Object.entries(p.notes))if(note)rows.push([p.name,p.intention||state.intention,'','',n,'Samostatný zápis',note]);download('Lila_cesta.csv','\uFEFF'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n'),'text/csv;charset=utf-8');}
function exportReport(){if(!state)return;const lines=['LÍLA · CESTA K SOBĚ',`Začátek: ${new Date(state.created).toLocaleString('cs-CZ')}`,`Téma: ${state.intention||'—'}`,''];for(const p of state.players){lines.push(p.name,`Záměr: ${p.intention||'—'}`,`Stav: ${p.finished?'dokončeno na 68':p.position===null?'čeká na vstup':`rozehráno na ${p.position}`}`);for(const [n,note]of Object.entries(p.notes))if(note)lines.push(`Pole ${n} · ${data.fields[+n-1].name}: ${note}`);lines.push('');}lines.push('DENÍK TAHŮ');for(const h of state.history)lines.push(`${state.players[h.player].name} · ${h.rolls.join(' + ')} · ${h.summary}`);download('Lila_ohlednuti.txt',lines.join('\n'),'text/plain;charset=utf-8');}
function validState(s){return s?.version===1&&s.rules==='johari-series-v1'&&Array.isArray(s.players)&&s.players.length>0&&s.players.length<=6&&s.players.every(p=>typeof p.name==='string'&&p.name.length<=40&&typeof p.intention==='string'&&(p.position===null||Number.isInteger(p.position)&&p.position>=1&&p.position<=72)&&typeof p.finished==='boolean'&&(!p.finished||p.position===68)&&p.notes&&typeof p.notes==='object'&&Object.entries(p.notes).every(([n,t])=>Number.isInteger(+n)&&+n>=1&&+n<=72&&typeof t==='string'))&&Number.isInteger(s.active)&&s.active>=0&&s.active<s.players.length&&Array.isArray(s.history)&&s.history.every(h=>Number.isInteger(h.player)&&h.player>=0&&h.player<s.players.length&&typeof h.time==='string'&&typeof h.summary==='string'&&Array.isArray(h.rolls)&&h.rolls.every(n=>Number.isInteger(n)&&n>=1&&n<=6)&&Array.isArray(h.path)&&h.path.every(n=>Number.isInteger(n)&&n>=1&&n<=72))&&Array.isArray(s.rolls)&&s.rolls.every(n=>n===6)&&typeof s.awaitNext==='boolean'&&typeof s.created==='string'&&typeof s.intention==='string'&&typeof s.message==='string';}
$('export').onclick=()=>{modal('Uchovej svou cestu',`<p>${state?'Export obsahuje jména, záměry i osobní poznámky všech hráčů. Sdílejte ho po vzájemné domluvě.':'Zahaj hru nebo obnov uložený soubor JSON.'}</p><div class="export-options"><button id="json" ${!state?'disabled':''}>JSON · záloha</button><button id="csv" ${!state?'disabled':''}>CSV · tabulka</button><button id="report" ${!state?'disabled':''}>TXT · ohlédnutí</button><button id="print-journal" ${!state?'disabled':''}>Vytisknout deník</button></div><h3>Obnovit cestu</h3><p>Soubor JSON nahradí současnou hru. Nejprve si ji případně zazálohuj.</p><label for="import">Vybrat zálohu JSON</label><input id="import" type="file" accept=".json,application/json"><p id="import-message" role="status"></p>`);$('json').onclick=exportJSON;$('csv').onclick=exportCSV;$('report').onclick=exportReport;$('print-journal').onclick=()=>{$('modal').close();window.print();};$('import').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>5e6)throw Error('Soubor je příliš velký.');const s=JSON.parse(await f.text());if(!validState(s))throw Error('Soubor nemá platný formát zálohy Líly.');backup=state;state=s;selected=state.players[state.active].position||1;render();$('modal').close();}catch(err){$('import-message').textContent=err.message;}};};
renderSetup();try{const saved=localStorage.getItem(key);if(saved){const s=JSON.parse(saved);if(validState(s))state=s;}}catch{storageOK=false;}showField(1);render();
